CREATE TABLE public.orgs (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version integer NOT NULL DEFAULT 0 CHECK (version >= 0), type varchar(16) NOT NULL CHECK (type IN ('company','bureau','agent','school')), name varchar(128) NOT NULL CHECK (length(btrim(name)) >= 2), code varchar(40) NOT NULL UNIQUE, region_code varchar(6) REFERENCES public.regions(code), status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), CONSTRAINT orgs_region_rule_check CHECK ((type = 'company' AND region_code IS NULL) OR (type IN ('bureau','school') AND region_code IS NOT NULL) OR type = 'agent'));
